// Built-in example labels (generated by tools/sample-labels) so anyone can try
// the app without preparing files.
import type { ApplicationData, FieldKey, FieldStatus, Verdict } from './domain/types';

export interface SampleCase {
  id: string;
  title: string;
  note: string;
  featured: boolean;
  images: string[];
  application: ApplicationData;
  expected: { overall: Verdict; fields: Partial<Record<FieldKey, FieldStatus>> };
}

const url = (file: string) => new URL(`samples/${file}`, document.baseURI).href;

let cache: Promise<SampleCase[]> | null = null;
export function loadSampleCases(): Promise<SampleCase[]> {
  cache ??= fetch(url('cases.json')).then((r) => {
    if (!r.ok) throw new Error('Could not load the example labels.');
    return r.json();
  });
  return cache;
}

export async function sampleFile(name: string): Promise<File> {
  const res = await fetch(url(name));
  if (!res.ok) throw new Error(`Could not load example image ${name}.`);
  return new File([await res.blob()], name, { type: res.headers.get('content-type') ?? 'image/jpeg' });
}

export async function sampleManifestFile(): Promise<File> {
  const res = await fetch(url('sample-batch.csv'));
  return new File([await res.text()], 'sample-batch.csv', { type: 'text/csv' });
}
